f = Failure["NotFound", <|"MessageTemplate" -> "File `1` missing", "MessageParameters" -> {"a.csv"}|>];
f["Message"]
FailureQ[Interpreter["Integer"]["abc"]] (* True *)

loadData[file_] := Enclose[Module[{raw, n},
   raw = Confirm[Import[file, "CSV"]];
   n = ConfirmBy[Length[raw], # > 0 &];
   ConfirmMatch[raw[[1]], {__String}];
   <|"rows" -> n, "header" -> raw[[1]]|>],
  (Print["load failed: ", #["Message"]]; $Failed) &]

Enclose[
  x = ConfirmBy[ToExpression[input], NumberQ, "not a number"];
  y = ConfirmQuiet[Sqrt[x - 1]];
  ConfirmMatch[y, _Real]]

myFit::badlen = "Expected `1` points but got `2`.";
myFit[data_] /; Length[data] < 3 := (Message[myFit::badlen, 3, Length[data]]; $Failed)
myFit[{1, 2}]

